12	describe('Puppeteer plugin test', () => {
13		let result, content, server;
14	
15		before('start webserver', () => server = startWebserver(SERVE_WEBSITE_PORT));
16		after('stop webserver', () => server.close())
17	
18		describe('Dynamic content', () => {
19			before('scrape website', async () => {
20				result = await scrape({
21					urls: [`http://localhost:${SERVE_WEBSITE_PORT}`],
22					directory: directory,
23					plugins: [ new PuppeteerPlugin({
24						scrollToBottom: { timeout: 50, viewportN: 10 }
25					}) ]
26				});
27			});
28			before('get content from file', () => {
29				content = fs.readFileSync(`${directory}/${result[0].filename}`).toString();
30			});
31			after('delete dir', () => fs.removeSync(directory));
32	
33			it('should have 1 item in result array', () => {
34				expect(result.length).eql(1);
35			});
36	
37			it('should render dymanic website', async () => {
38				expect(content).to.contain('<div id="root">Hello world from JS!</div>');
39			});
40	
41			it('should render special characters correctly', async () => {
42				expect(content).to.contain('<div id="special-characters-test">7년 동안 한국에서 살았어요. Слава Україні!</div>');
43			});
44		});
45	
46		// Regression test for https://github.com/website-scraper/website-scraper-puppeteer/issues/115
47		// The page js rotates the session cookie; the rotated cookie must be used
48		// for subsequent requests instead of the initially configured one.
49		// Runs with the default (unlimited) requestConcurrency: page renders
50		// must not overlap with each other or with in-flight plain requests.
51		describe('Session cookie rotated by page js', () => {
52			const SESSION_SERVER_PORT = 4568;
53			let sessionServer, files;
54	
55			before('start session webserver', () => sessionServer = startSessionRotatingWebserver(SESSION_SERVER_PORT));
56			after('stop session webserver', () => sessionServer.close());
57	
58			before('scrape website', async () => {
59				await scrape({
60					urls: [`http://localhost:${SESSION_SERVER_PORT}/`],
61					directory: directory,
62					recursive: true,
63					request: {
64						headers: { Cookie: 'session=token-1' }
65					},
66					urlFilter: url => url.startsWith(`http://localhost:${SESSION_SERVER_PORT}`),
67					plugins: [ new PuppeteerPlugin({
68						// wait for the session-rotating fetch() to complete before the page is closed
69						gotoOptions: { waitUntil: 'networkidle0' }
70					}) ]
71				});
72			});
73			before('get content from files', () => {
74				files = {};
75				for (const name of ['index', 'page2', 'page3', 'page4', 'page5']) {
76					files[name] = fs.readFileSync(`${directory}/${name}.html`).toString();
77				}
78			});
79			after('delete dir', () => fs.removeSync(directory));
80	
81			it('should stay logged in on the first page', () => {
82				expect(files.index).to.contain('LOGGED-IN');
83			});
84	
85			it('should stay logged in on subsequent pages', () => {
86				for (const name of ['page2', 'page3', 'page4', 'page5']) {
87					expect(files[name], name).to.contain('LOGGED-IN');
88				}
89			});
90	
91			it('should never present a stale token', () => {
92				expect(sessionServer.sessionDestroyed).to.eql(false);
93			});
94	
95			it('should use the rotated cookie for subsequent website-scraper requests', () => {
96				const scraperRequests = sessionServer.requestLog.filter(request => request.url === '/page2.html' && !request.fromBrowser);
97				expect(scraperRequests).to.have.lengthOf(1);
98				expect(scraperRequests[0].cookie).to.eql('session=token-2');
99			});
100		});
101	
102		// got follows redirects internally, so cookies set on intermediate hops
103		// are only visible through the cookie jar - not in the final response.
104		describe('Cookie set on a redirect hop', () => {
105			const REDIRECT_SERVER_PORT = 4569;
106			let redirectServer, homeContent;
107	
108			before('start redirecting webserver', () => redirectServer = startRedirectingWebserver(REDIRECT_SERVER_PORT));
109			after('stop redirecting webserver', () => redirectServer.close());
110	
111			before('scrape website', async () => {
112				await scrape({
113					urls: [`http://localhost:${REDIRECT_SERVER_PORT}/`],
114					directory: directory,
115					request: {
116						headers: { Cookie: 'session=token-1' }
117					},
118					plugins: [ new PuppeteerPlugin() ]
119				});
120			});
121			before('get content from file', () => {
122				homeContent = fs.readFileSync(`${directory}/index.html`).toString();
123			});
124			after('delete dir', () => fs.removeSync(directory));
125	
126			it('should send the configured cookie to the redirecting url', () => {
127				const requests = redirectServer.requestLog.filter(request => request.url === '/' && !request.fromBrowser);
128				expect(requests).to.have.lengthOf(1);
129				expect(requests[0].cookie).to.eql('session=token-1');
130			});
131	
132			it('should send the cookie set by the redirect to the redirect target', () => {
133				const requests = redirectServer.requestLog.filter(request => request.url === '/home.html' && !request.fromBrowser);
134				expect(requests).to.have.lengthOf(1);
135				expect(requests[0].cookie).to.eql('session=token-2');
136			});
137	
138			it('should render the redirect target in puppeteer with the cookie set by the redirect', () => {
139				expect(homeContent).to.contain('<h1>session=token-2</h1>');
140			});
141	
142			it('should ignore a cookie rejected by the browser', () => {
143				// the scrape completed (see before hook) despite the __Secure- cookie
144				// sent over http, and the valid cookie was kept
145				expect(homeContent).to.contain('<h1>session=token-2</h1>');
146			});
147		});
148	
149		describe('exclusiveRendering: false', () => {
150			let plainResult, plainContent;
151	
152			before('scrape website', async () => {
153				plainResult = await scrape({
154					urls: [`http://localhost:${SERVE_WEBSITE_PORT}`],
155					directory: directory,
156					plugins: [ new PuppeteerPlugin({ exclusiveRendering: false }) ]
157				});
158			});
159			before('get content from file', () => {
160				plainContent = fs.readFileSync(`${directory}/${plainResult[0].filename}`).toString();
161			});
162			after('delete dir', () => fs.removeSync(directory));
163	
164			it('should render dynamic website without the render lock', () => {
165				expect(plainContent).to.contain('<div id="root">Hello world from JS!</div>');
166			});
167		});
168	
169		describe('CJK content with charset only in meta tag', () => {
170			let cjkResult, cjkContent;
171	
172			before('scrape website', async () => {
173				cjkResult = await scrape({
174					urls: [`http://localhost:${SERVE_WEBSITE_PORT}/cjk.html`],
175					directory: directory,
176					plugins: [ new PuppeteerPlugin() ]
177				});
178			});
179			before('get content from file', () => {
180				cjkContent = fs.readFileSync(`${directory}/${cjkResult[0].filename}`).toString();
181			});
182			after('delete dir', () => fs.removeSync(directory));
183	
184			// Regression test for https://github.com/website-scraper/website-scraper-puppeteer/pull/103
185			// Saving the page as a binary string corrupted these characters on disk.
186			it('should save CJK characters without corruption', () => {
187				expect(cjkContent).to.contain('<div id="cjk-characters-test">磁致伸缩位移传感器 影响大跨度桥梁施工控制的因素</div>');
188			});
189		});
190	});
191	
192	// Simulates a website which rotates the session cookie via an ajax call
193	// (like WordPress heartbeat / WooCommerce fragments do). Rotation invalidates
194	// the previous token, and presenting a stale token destroys the whole session
195	// (like WordPress security plugins do on suspected session hijacking).
196	// Pages link to each other so that sibling pages get requested concurrently:
197	// index -> page2, page3; page2 -> page4; page3 -> page5.
198	function startSessionRotatingWebserver (port) {
199		const validTokens = new Set(['token-1']);
200		const seenTokens = new Set(['token-1']);
201		let tokenCounter = 1;
202		const requestLog = [];
203		const links = {
204			'/': ['/page2.html', '/page3.html'],
205			'/page2.html': ['/page4.html'],
206			'/page3.html': ['/page5.html']
207		};
208	
209		const server = http.createServer((req, res) => {
210			if (req.url === '/favicon.ico') {
211				// requested by Chrome in parallel with the page's own requests, not session-related
212				res.writeHead(404).end();
213				return;
214			}
215			// Every request takes a while to be processed, so requests sent concurrently
216			// (by a page render or by website-scraper) overlap and a rotation triggered
217			// by one of them lands before the others are validated.
218			setTimeout(() => handle(req, res), 100);
219		});
220	
