			container.style.overflow = 'auto';
			const inner = document.createElement('div');
			inner.style.height = '5000px';
			container.appendChild(inner);
			document.body.appendChild(container);

			setTimeout(() => container.remove(), 100);
		});

		let caught = null;
		try {
